	knownrebecs {
		Pong pong;
	}

	statevars {
		int count;
	}

	Ping(Pong pong) {
		self.pong = pong;
		count = 0;
	}

	msgsrv startMessage() {
		println("Ping started the game!");
		pong.pingMessage();
	}

	msgsrv pongMessage() {
		count = count + 1;
		println("Ping received pong #" + count + " from pong");
